procedure.step:
      Fix the upstream narrowing logic so the variable resolves to a concrete type.

// Before: value is `never` here because all cases handled above
// Fix: add the missing case or remove the unreachable branch
switch (status) {
  case "open": return handleOpen();
  case "closed": return handleClosed();
  default: {
    const _exhaustive: never = status; // ✅ intentional exhaustive check
    throw new Error(`Unknown status: ${_exhaustive}`);
  }
}

      Narrow using a runtime check:

if (typeof value === "string") {
  // value is string here
} else if (value instanceof Error) {
  // value is Error here
}

      For depth ≤2, bracket syntax is acceptable:

const list: string[] = [];
const matrix: string[][] = [];

      Move the declarations to the types module and export them:

// types/task.ts
export interface Task {
  id: number;
  title: string;
  status: "open" | "closed";
}

      If the return type is too complex to annotate, suppress the ESLint
      rule with a reason:

// eslint-disable-next-line @typescript-eslint/explicit-function-return-type -- complex generated union
const buildConfig = () => ({ /* … */ });
